// Session ids generated by the page must be UUIDv4 (protocol.md §2), including on plain-http pages where
// crypto.randomUUID doesn't exist.
import { parseSessionId } from "@voice-chat-agent/shared/protocol";
import { afterEach, describe, expect, it, vi } from "vitest";
import { randomId } from "../src/lib/ids";

const realCrypto = globalThis.crypto;

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("randomId", () => {
  it("returns a UUIDv4 from crypto.randomUUID when available", () => {
    const id = randomId();
    expect(parseSessionId(id)).toBe(id);
  });

  it("builds a UUIDv4 from crypto.getRandomValues when randomUUID is missing (insecure context)", () => {
    vi.stubGlobal("crypto", { getRandomValues: (array: Uint8Array<ArrayBuffer>) => realCrypto.getRandomValues(array) });
    const ids = new Set(Array.from({ length: 1000 }, () => randomId()));
    expect(ids.size).toBe(1000);
    for (const id of ids) expect(parseSessionId(id)).toBe(id);
  });

  it("sets the version and variant bits whatever the random bytes are", () => {
    for (const [fill, expected] of [
      [0x00, "00000000-0000-4000-8000-000000000000"],
      [0xff, "ffffffff-ffff-4fff-bfff-ffffffffffff"],
    ] as const) {
      vi.stubGlobal("crypto", { getRandomValues: (array: Uint8Array) => array.fill(fill) });
      expect(randomId()).toBe(expected);
    }
  });

  it("never falls back to a non-random id", () => {
    vi.stubGlobal("crypto", {
      getRandomValues: () => {
        throw new Error("no randomness");
      },
    });
    expect(() => randomId()).toThrow("no randomness");
  });
});
